namespace ghidra.app.plugin.core.script;



using docking.widgets.searchlist;
using ghidra.app.script;

/**
 * Model for the script selection search list that organizes scripts into
 * "Recent Scripts" and "All Scripts" categories.
 */
public class ScriptsModel : DefaultSearchListModel<ScriptInfo> {

	private List<ScriptInfo> allScripts;
	private List<string> recentScriptNames;

	public ScriptsModel(List<ScriptInfo> allScripts, List<string> recentScriptNames) {
		this.allScripts = allScripts;
		this.recentScriptNames = recentScriptNames != null ? recentScriptNames : new();
		populateModel();
	}

	private void populateModel() {
		// Create map for quick lookup
		Map<string, ScriptInfo> scriptMap = new();
		foreach (ScriptInfo script in allScripts) {
			scriptMap.put(script.getName(), script);
		}

		// Add recent scripts first (these should be sorted by most recently used)
		List<ScriptInfo> recentScripts = new();
		Set<string> addedScripts = new();
		foreach (string recentName in recentScriptNames) {
			ScriptInfo script = scriptMap.get(recentName);
			if (script != null) {
				recentScripts.add(script);
				addedScripts.add(recentName);
			}
		}

		if (!recentScripts.isEmpty()) {
			add(ScriptGroup.RECENT_SCRIPTS.getDisplayName(), recentScripts);
		}

		// Add all other scripts (alphabetically sorted)
		List<ScriptInfo> otherScripts = new();
		foreach (ScriptInfo script in allScripts) {
			if (!addedScripts.contains(script.getName())) {
				otherScripts.add(script);
			}
		}
		otherScripts.sort(Comparator.comparing(ScriptInfo.getName));

		add(ScriptGroup.ALL_SCRIPTS.getDisplayName(), otherScripts);
	}
}
